/* js/data-code-course.js - GENERATED by tools/build.py from data/code-course.json (Coding from zero). Do not edit. */
(function (S) {
  'use strict';
  S.CODE_COURSE = {"title":"Coding from zero","lang":"C++","note":"Own words. Lessons follow the HSC Computer Science C++ syllabus order. Task cases use the same rule as data/cs-cpp-cases.json.","lessons":[{"id":"program","t":"What is a program?","why":"Before any code: what a computer does with your instructions.","idea":["A computer cannot think. It follows instructions, one after another, very fast. A program is a list of such instructions, written in a language the computer can be made to understand.","C++ is one such language. You write the program as text (the source code). A tool called a compiler turns that text into a file the computer can run. When the program runs, it can show text on the screen (output) and read what you type (input).","If you break a rule of the language, for example forget a semicolon, the compiler stops and shows an error. That is normal: every programmer reads errors every day."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hello, I am learning C++!\";\n    return 0;\n}\n","lines":[[1,"Brings in iostream, the part of C++ that knows how to print and read."],[2,"Lets us write cout instead of the longer std::cout."],[4,"main is where every C++ program starts running."],[5,"cout prints the text between the quotes on the screen."],[6,"return 0 tells the computer the program ended without a problem."],[7,"The closing brace ends main."]],"quiz":[{"q":"What does a compiler do?","options":["Runs the internet","Turns your source code into a program the computer can run","Types the code for you","Stores your marks"],"ans":1,"why":"The compiler translates the text you wrote into a runnable program, and reports errors if a rule is broken."},{"q":"Where does every C++ program start running?","options":["At the first line","At #include","In the function main","At the last line"],"ans":2,"why":"Execution always begins inside main()."}],"task":{"q":"Change the program so that it prints your own message: Hello Study OS","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"","has":["hello","study","os"]}],"hint":"Use cout << \"Hello Study OS\"; inside main.","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hello Study OS\";\n    return 0;\n}\n"}},{"id":"output","t":"Printing with cout","why":"Show text and numbers, on one line or many.","idea":["`cout` (say \"see-out\") sends things to the screen. The arrows `<<` point the way the data goes: from your program out to the screen.","You can chain several pieces: `cout << \"Marks: \" << 45;` prints Marks: 45. Text goes inside double quotes. Numbers do not need quotes.","To go to the next line, print `endl` or the special character `\"\\n\"`. Without them everything stays on one line."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Name: Riya\" << endl;\n    cout << \"Marks: \" << 45 << endl;\n    cout << \"Total: \" << 45 + 40;\n    return 0;\n}\n","lines":[[5,"Prints Name: Riya, then endl moves to a new line."],[6,"Text and a number in one statement, joined with <<."],[7,"C++ works out 45 + 40 first, so this prints Total: 85."]],"quiz":[{"q":"What does cout << \"5 + 3\"; print?","options":["8","5 + 3","53","An error"],"ans":1,"why":"Inside quotes it is text, printed exactly as written. Without quotes, cout << 5 + 3; would print 8."},{"q":"Which one moves the output to a new line?","options":["endl","end","next","line"],"ans":0,"why":"endl (end line) or \"\\n\" starts a new line."}],"task":{"q":"Print these two lines: first \"Physics 50\", then \"Chemistry 48\" on the next line.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"","has":["physics","50","chemistry","48"]}],"hint":"Two cout statements, with endl after the first.","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Physics 50\" << endl;\n    cout << \"Chemistry 48\" << endl;\n    return 0;\n}\n"}},{"id":"variables","t":"Variables and data types","why":"Store values in named boxes and use them later.","idea":["A variable is a named box in memory that holds one value. Before using it you declare it: you give its type and its name, for example `int marks;`","The type says what kind of value the box holds: `int` for whole numbers (45), `float` for numbers with a point (7.5), `char` for one character (`'A'`), and `bool` for true or false.","The = sign puts a value into the box (assignment): `marks = 45;` You can change it later; the old value is replaced."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int marks = 45;\n    float percent = 90.5;\n    char grade = 'A';\n    marks = marks + 2;\n    cout << marks << \" \" << percent << \" \" << grade;\n    return 0;\n}\n","lines":[[5,"A whole-number box called marks, starting at 45."],[6,"A box for a decimal number."],[7,"A box for one character; single quotes are used for a char."],[8,"Take the old value (45), add 2, and store 47 back in marks."],[9,"Prints 47 90.5 A."]],"quiz":[{"q":"Which type fits the value 3.75?","options":["int","char","float","bool"],"ans":2,"why":"A number with a decimal point needs float (or double). int keeps only whole numbers."},{"q":"After int x = 10; x = x * 3; what is x?","options":["10","13","30","3"],"ans":2,"why":"x * 3 uses the old value 10, gives 30, and 30 is stored back in x."}],"task":{"q":"Make an int variable length = 8 and an int variable width = 5, and print their product (the area).","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"","has":["40"]}],"hint":"int length = 8; int width = 5; cout << length * width;","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int length = 8;\n    int width = 5;\n    cout << \"Area = \" << length * width;\n    return 0;\n}\n"}},{"id":"input","t":"Reading input with cin","why":"Let the user type values while the program runs.","idea":["`cin` (say \"see-in\") reads what the user types. The arrows `>>` point from the keyboard into your variable: `cin >> marks;`","The program waits at `cin` until a value is typed. You can read several values in one line: `cin >> a >> b;` reads two numbers separated by a space.","Good programs print a short prompt first, like `\"Enter a number: \"`, so the user knows what to type."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b;\n    cout << \"Enter two numbers: \";\n    cin >> a >> b;\n    cout << \"Sum = \" << a + b;\n    return 0;\n}\n","lines":[[5,"Two int boxes, declared in one line."],[6,"A prompt, so the user knows what to do."],[7,"Reads the first number into a and the second into b."],[8,"Prints their sum."]],"quiz":[{"q":"Which line reads a number into n?","options":["cout >> n;","cin >> n;","cin << n;","read n;"],"ans":1,"why":"cin with >> reads into a variable. cout with << prints."},{"q":"In the lab, where do you give the program its input?","options":["In the Input box below the program","Inside the cout","Nowhere, it guesses","In the file name"],"ans":0,"why":"The Input box is what the user would type; each value can go on its own line or be separated by spaces."}],"task":{"q":"Read a number and print its square. Example: input 7 prints 49.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"7","has":["49"]},{"in":"12","has":["144"]}],"hint":"int n; cin >> n; cout << n * n;","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cout << \"Enter a number: \";\n    cin >> n;\n    cout << \"Square = \" << n * n;\n    return 0;\n}\n"}},{"id":"operators","t":"Arithmetic operators","why":"Add, subtract, divide, and the useful remainder operator.","idea":["C++ has `+ - * /` for arithmetic. Watch division: when both numbers are int, the answer is also int and the part after the point is dropped. `7 / 2` gives 3, not 3.5.","The `%` operator gives the remainder of a division between two ints: `7 % 2` is 1. It tells whether a number is even `(n % 2 == 0)` and it gives the last digit of a number `(n % 10)`.","Order of work is like in maths: `* / %` before `+ -`. Use brackets to be clear: `(a + b) / 2`."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 157;\n    cout << n / 10 << endl;\n    cout << n % 10 << endl;\n    cout << (2 + 3) * 4;\n    return 0;\n}\n","lines":[[6,"157 / 10 is 15 (int division drops the .7)."],[7,"157 % 10 is 7, the last digit."],[8,"Brackets first: 5 * 4 = 20."]],"quiz":[{"q":"What is 17 / 5 when both are int?","options":["3.4","3","4","2"],"ans":1,"why":"Integer division keeps only the whole part: 3."},{"q":"What is 17 % 5?","options":["3","2","5","0"],"ans":1,"why":"17 = 5 x 3 + 2, so the remainder is 2."}],"task":{"q":"Read a 3-digit number and print its last digit and the number without its last digit. Example: 482 prints 2 and 48.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"482","has":["2","48"]},{"in":"907","has":["7","90"]}],"hint":"Last digit: n % 10. Without it: n / 10.","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    cout << \"Last digit: \" << n % 10 << endl;\n    cout << \"Rest: \" << n / 10 << endl;\n    return 0;\n}\n"}},{"id":"decisions","t":"Decisions with if and else","why":"Make the program choose what to do.","idea":["`if` checks a condition. If it is true, the block in braces runs; `else` gives the other choice: `if (marks >= 35) { pass } else { fail }`.","Comparison operators: `==` (equal; two signs!), `!=` (not equal), `<, >, <=, >=`. One = puts a value in a variable; `==` compares.","Join conditions with `&&` (and: both must be true) or `||` (or: at least one true). Use `else if` for more than two choices."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int marks;\n    cin >> marks;\n    if (marks >= 75) {\n        cout << \"Distinction\";\n    } else if (marks >= 35) {\n        cout << \"Pass\";\n    } else {\n        cout << \"Fail\";\n    }\n    return 0;\n}\n","lines":[[7,"First test: 75 or more."],[9,"Checked only if the first test was false."],[11,"Runs when no condition above was true."]],"quiz":[{"q":"Which condition checks that x equals 5?","options":["x = 5","x == 5","x => 5","x := 5"],"ans":1,"why":"Comparison uses ==. A single = would put 5 into x."},{"q":"For marks = 60, what does the example print?","options":["Distinction","Pass","Fail","Nothing"],"ans":1,"why":"60 is not >= 75, but it is >= 35, so Pass."}],"task":{"q":"Read a number and print Even if it is even, otherwise print Odd.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"14","has":["even"],"no":["odd"]},{"in":"9","has":["odd"],"no":["even"]}],"hint":"if (n % 2 == 0) cout << \"Even\"; else cout << \"Odd\";","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    if (n % 2 == 0)\n        cout << \"Even\";\n    else\n        cout << \"Odd\";\n    return 0;\n}\n"}},{"id":"for","t":"Repeating with a for loop","why":"Do the same work many times without writing it many times.","idea":["A loop repeats a block. The for loop is best when you know how many times: `for (int i = 1; i <= 5; i++) { ... }` runs 5 times, with i = 1, 2, 3, 4, 5.","The three parts: start `(int i = 1)`, condition checked before every round `(i <= 5)`, and change after every round `(i++` adds 1).","A common pattern: keep a total. Start `sum = 0`, and in each round add to it: `sum = sum + i;`"],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int sum = 0;\n    for (int i = 1; i <= 5; i++) {\n        cout << i << \" \";\n        sum = sum + i;\n    }\n    cout << endl << \"Sum = \" << sum;\n    return 0;\n}\n","lines":[[5,"The total starts at 0."],[6,"i goes 1, 2, 3, 4, 5; the loop stops when i becomes 6."],[7,"Prints the current i."],[8,"Adds i to the total."],[10,"After the loop: prints Sum = 15."]],"quiz":[{"q":"How many times does for (int i = 0; i < 4; i++) run?","options":["3","4","5","Forever"],"ans":1,"why":"i takes 0, 1, 2, 3: four rounds. At i = 4 the condition is false."},{"q":"What does i++ do?","options":["Doubles i","Adds 1 to i","Prints i","Sets i to 0"],"ans":1,"why":"i++ is short for i = i + 1."}],"task":{"q":"Read n and print the multiplication table of n from 1 to 10 (n x 1 up to n x 10). Example: 3 prints 3 6 9 ... 30.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"3","has":["3","6","9","12","15","18","21","24","27","30"]},{"in":"7","has":["7","14","21","70"]}],"hint":"for (int i = 1; i <= 10; i++) cout << n * i << \" \";","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 1; i <= 10; i++)\n        cout << n << \" x \" << i << \" = \" << n * i << endl;\n    return 0;\n}\n"}},{"id":"while","t":"while loops","why":"Repeat as long as something is true, when you do not know how many times.","idea":["A while loop checks its condition first and repeats while it stays true: `while (n > 0) { ... }`. Something inside must change, or the loop never ends.","This fits jobs like taking a number apart digit by digit: `n % 10` gives the last digit and `n / 10` removes it, until n becomes 0.","`do { ... } while (condition);` is the same, except the block always runs at least once, because the check is at the end."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 4721, digits = 0;\n    while (n > 0) {\n        n = n / 10;\n        digits++;\n    }\n    cout << \"Digits: \" << digits;\n    return 0;\n}\n","lines":[[6,"Repeat while there are digits left."],[7,"Remove the last digit: 4721 becomes 472, then 47, 4, 0."],[8,"Count one digit each round."],[10,"Prints Digits: 4."]],"quiz":[{"q":"What happens if nothing inside a while loop changes its condition?","options":["It runs once","It never ends (infinite loop)","The compiler fixes it","It skips the loop"],"ans":1,"why":"If the condition stays true, the loop repeats forever."},{"q":"Which loop always runs its block at least once?","options":["for","while","do-while","if"],"ans":2,"why":"do-while checks the condition after the block."}],"task":{"q":"Read a number and print the sum of its digits. Example: 4721 gives 14.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"4721","has":["14"]},{"in":"9005","has":["14"]},{"in":"36","has":["9"]}],"hint":"while (n > 0) { sum = sum + n % 10; n = n / 10; }","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, sum = 0;\n    cin >> n;\n    while (n > 0) {\n        sum = sum + n % 10;\n        n = n / 10;\n    }\n    cout << \"Sum of digits = \" << sum;\n    return 0;\n}\n"}},{"id":"arrays","t":"Arrays: many values in one name","why":"Keep a list of values, like the marks of 5 subjects.","idea":["An array is a row of boxes of the same type under one name: `int marks[5];` makes 5 int boxes. Each box has a position number called the index, starting at 0. So the boxes are `marks[0]` to `marks[4]`.","Loops and arrays go together: `for (int i = 0; i < 5; i++) cin >> marks[i];` reads all five.","Never use an index outside the array (`marks[5]` here). C++ will not stop you, and the program can give wrong answers or crash."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int m[5] = {45, 38, 50, 41, 47};\n    int big = m[0];\n    for (int i = 1; i < 5; i++)\n        if (m[i] > big)\n            big = m[i];\n    cout << \"Highest = \" << big;\n    return 0;\n}\n","lines":[[5,"An array of 5 marks, filled at once with braces."],[6,"Start by taking the first value as the highest."],[7,"Look at the others, index 1 to 4."],[8,"If one is bigger, remember it."],[10,"Prints Highest = 50."]],"quiz":[{"q":"In int a[10]; what is the index of the last box?","options":["10","9","1","11"],"ans":1,"why":"Indexes start at 0, so ten boxes are a[0] to a[9]."},{"q":"What does m[2] hold in the example?","options":["38","50","45","41"],"ans":1,"why":"m[0] = 45, m[1] = 38, m[2] = 50."}],"task":{"q":"Read 5 numbers into an array and print their total and their average. Example: 10 20 30 40 50 gives total 150 and average 30.","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"10 20 30 40 50","has":["150","30"]},{"in":"1 2 3 4 5","has":["15","3"]}],"hint":"Read with a loop, add each value to sum, then print sum and sum / 5.0.","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5], sum = 0;\n    for (int i = 0; i < 5; i++) {\n        cin >> a[i];\n        sum = sum + a[i];\n    }\n    cout << \"Total = \" << sum << endl;\n    cout << \"Average = \" << sum / 5.0 << endl;\n    return 0;\n}\n"}},{"id":"functions","t":"Functions: name a piece of work","why":"Write a job once and use it many times.","idea":["A function is a named block of code that does one job. It can take values (parameters) and give back a result (return value): `int square(int x) { return x * x; }`","You call it by its name: `square(5)` gives 25. `main` itself is a function, the one that runs first.","Functions keep programs short and clear. In the board paper you will meet them as member functions inside classes."],"code":"#include <iostream>\nusing namespace std;\n\nint cube(int x) {\n    return x * x * x;\n}\n\nint main() {\n    cout << cube(2) << endl;\n    cout << cube(3) + 1;\n    return 0;\n}\n","lines":[[4,"A function named cube: it takes an int x and returns an int."],[5,"Sends back x * x * x."],[9,"Calls cube with 2 and prints 8."],[10,"cube(3) is 27, plus 1 prints 28."]],"quiz":[{"q":"What does return do in a function?","options":["Ends the whole program","Sends a value back to where the function was called","Prints the value","Repeats the function"],"ans":1,"why":"return gives the result back to the caller."},{"q":"With int add(int a, int b) { return a + b; } what is add(4, 6)?","options":["46","10","24","2"],"ans":1,"why":"a = 4 and b = 6, so it returns 10."}],"task":{"q":"Write a function int bigger(int a, int b) that returns the larger number. In main read two numbers and print bigger of them.","starter":"#include <iostream>\nusing namespace std;\n\nint bigger(int a, int b) {\n    // your code\n}\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"8 3","has":["8"]},{"in":"-2 5","has":["5"]}],"hint":"if (a > b) return a; else return b;","solution":"#include <iostream>\nusing namespace std;\n\nint bigger(int a, int b) {\n    if (a > b)\n        return a;\n    return b;\n}\n\nint main() {\n    int x, y;\n    cin >> x >> y;\n    cout << \"Bigger = \" << bigger(x, y);\n    return 0;\n}\n"}},{"id":"classes","t":"Classes and objects","why":"The start of object oriented programming, the biggest part of Paper I.","idea":["A class is a design for a new type that keeps data and the functions that use it together. An object is a real variable made from that design.","Inside a class, `private` data can only be used by the class's own functions; `public` functions are what the rest of the program may call.","A constructor is a special function with the same name as the class. It runs by itself when an object is made, and sets the starting values."],"code":"#include <iostream>\nusing namespace std;\n\nclass Student {\n    int marks;\npublic:\n    Student(int m) { marks = m; }\n    void show() { cout << \"Marks: \" << marks << endl; }\n    bool passed() { return marks >= 35; }\n};\n\nint main() {\n    Student s(62);\n    s.show();\n    if (s.passed()) cout << \"Passed\";\n    return 0;\n}\n","lines":[[4,"Design a new type called Student."],[5,"marks is private: only Student's functions can touch it."],[7,"The constructor stores the starting marks."],[8,"A member function that prints the marks."],[12,"Make an object s; the constructor gets 62."],[13,"Call a member function with a dot: s.show()."]],"quiz":[{"q":"What is an object?","options":["A function","A variable made from a class","A loop","A header file"],"ans":1,"why":"The class is the design; each object is a real variable of that type."},{"q":"When does a constructor run?","options":["When you call it by hand","Automatically when an object is created","At the end of main","Never"],"ans":1,"why":"It runs by itself when the object is made, to set it up."}],"task":{"q":"Make a class Rectangle with private length and width, a constructor taking both, and a function area() that returns length * width. In main read two numbers, make a Rectangle and print its area.","starter":"#include <iostream>\nusing namespace std;\n\nclass Rectangle {\n    // data\npublic:\n    // constructor and area()\n};\n\nint main() {\n    \n    return 0;\n}\n","cases":[{"in":"6 4","has":["24"]},{"in":"10 3","has":["30"]}],"hint":"Rectangle(int l, int w) { length = l; width = w; }  int area() { return length * width; }","solution":"#include <iostream>\nusing namespace std;\n\nclass Rectangle {\n    int length, width;\npublic:\n    Rectangle(int l, int w) { length = l; width = w; }\n    int area() { return length * width; }\n};\n\nint main() {\n    int l, w;\n    cin >> l >> w;\n    Rectangle r(l, w);\n    cout << \"Area = \" << r.area();\n    return 0;\n}\n"}},{"id":"errors","t":"Reading errors and fixing them","why":"Every programmer meets errors. Learn to read them calmly.","idea":["A compile error means a language rule was broken, so the program could not be built. The message names the line: `prog.cc:6` means line 6. Look at that line and the one above it.","The usual ones: a missing semicolon (`expected ';'`), a name typed wrongly or not declared (`was not declared in this scope`), a missing brace, or quotes not closed.","A program can also compile and still be wrong (a logic error): it runs but prints the wrong answer. Test it with inputs whose answer you already know."],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 3; i++)\n        total = total + i;\n    cout << \"Total = \" << total;\n    return 0;\n}\n","lines":[[5,"Declare and set total before using it. Without = 0 it would hold a garbage value (a logic error)."],[7,"Each statement ends with a semicolon."],[8,"The name must be spelt the same everywhere: total, not Total."]],"quiz":[{"q":"The compiler says: expected ';' before cout. What is the most likely fix?","options":["Add a semicolon at the end of the line before cout","Delete cout","Add #include again","Restart the phone"],"ans":0,"why":"The statement before cout was not ended with a semicolon."},{"q":"A program runs but prints the wrong answer. What kind of error is it?","options":["Compile error","Logic error","Network error","No error"],"ans":1,"why":"It obeys the language rules, but the steps are wrong: a logic error."}],"task":{"q":"This program has 3 mistakes. Fix it so that it reads a number and prints double the number.\n(The starter in the editor has the mistakes.)","starter":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n\n    cin >> n;\n    cout << \"Double = \" << N * 2\n    return 0;\n}\n","cases":[{"in":"21","has":["42"]},{"in":"5","has":["10"]}],"hint":"Look for two missing semicolons and a name with the wrong capital letter.","solution":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    cout << \"Double = \" << n * 2;\n    return 0;\n}\n"}}]};
})((window.SOS = window.SOS || {}));
